"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[617],{6612(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>g,frontMatter:()=>l,metadata:()=>s,toc:()=>u});const s=JSON.parse('{"id":"part1-enterprise-ai-delivery/provisioning-services-scale","title":"Steps 4\u20135 on GCP: Services, Provisioning, Latency, and Scale","description":"This tutorial expands Step 4 and Step 5 for your multi-tenant Document Q&A system on GCP. It answers: which exact services you provision, why GKE / Pub/Sub / Cloud Tasks, what latency targets are acceptable, and how t...","source":"@site/docs/part1-enterprise-ai-delivery/11-provisioning-services-scale.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/11-provisioning-services-scale","permalink":"/tutorials/part1-enterprise-ai-delivery/11-provisioning-services-scale","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":11,"frontMatter":{"title":"Steps 4\u20135 on GCP: Services, Provisioning, Latency, and Scale","slug":"/part1-enterprise-ai-delivery/11-provisioning-services-scale","description":"This tutorial expands Step 4 and Step 5 for your multi-tenant Document Q&A system on GCP. It answers: which exact services you provision, why GKE / Pub/Sub / Cloud Tasks, what latency targets are acceptable, and how t...","sidebar_label":"11. Provisioning, services, scale","pagination_label":"11. Provisioning, services, scale","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"10. HLD to LLD and sprint plan","permalink":"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan"},"next":{"title":"Part overview","permalink":"/tutorials/part2-backend-platform-security/overview"}}');var i=n(4848),r=n(8453),a=n(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/11-provisioning-services-scale.html","route":"/part1-enterprise-ai-delivery/11-provisioning-services-scale","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"Step 4\u20135 (GCP): Provisioning Tickets + Concrete Service Choices + Latency + 1000s of Users","title":"Steps 4\u20135 on GCP: Services, Provisioning, Latency, and Scale","description":"This tutorial expands Step 4 and Step 5 for your multi-tenant Document Q&A system on GCP. It answers: which exact services you provision, why GKE / Pub/Sub / Cloud Tasks, what latency targets are acceptable, and how t...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-concrete-reference-architecture-gcp-services","label":"1) Concrete reference architecture (GCP services)"},{"id":"2-document-extraction-tooling-where-implemented-and-why","label":"2) Document extraction tooling: where implemented and why"},{"id":"3-why-gke-for-the-backend-and-what-cloud-run-would-change","label":"3) Why GKE for the backend (and what Cloud Run would change)"},{"id":"4-why-pub-sub-cloud-tasks-and-what-they-solve","label":"4) Why Pub/Sub + Cloud Tasks (and what they solve)"},{"id":"5-latency-targets-what-s-acceptable-and-how-to-meet-it","label":"5) Latency targets: what\u2019s acceptable and how to meet it"},{"id":"6-handling-1000s-of-simultaneous-users-gke-fastapi-external-llm-constraints","label":"6) Handling 1000s of simultaneous users (GKE + FastAPI + external LLM constraints)"},{"id":"7-step-4-provisioning-and-dependency-tickets-what-to-raise-exactly","label":"7) Step 4: Provisioning & dependency tickets (what to raise, exactly)"},{"id":"8-step-5-engineering-kickoff-internal-make-good-unambiguous","label":"8) Step 5: Engineering kickoff (internal) \u2014 make \u201cgood\u201d unambiguous"},{"id":"9-quick-acceptable-alternatives-cheat-sheet-if-approvals-block-you","label":"9) Quick \u201cacceptable alternatives\u201d cheat sheet (if approvals block you)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial expands Step 4 and Step 5 for your multi-tenant Document Q&amp;A system on <strong>GCP</strong>.\\n      It answers: <strong>which exact services</strong> you provision, <strong>why GKE / Pub/Sub / Cloud Tasks</strong>,\\n      what <strong>latency targets</strong> are acceptable, and how to handle <strong>1000s of simultaneous users</strong>\\n      in a large enterprise.\\n    </p>\\n\\n    <h2 id=\\"1-concrete-reference-architecture-gcp-services\\">1) Concrete reference architecture (GCP services)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Capability</th>\\n            <th>Concrete GCP implementation</th>\\n            <th>Notes (bank/enterprise friendly)</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>Frontend</strong></td>\\n            <td>Cloud Run (React static via CDN or server-render), behind HTTPS LB</td>\\n            <td>Public entry, simple scaling; no direct access to data stores</td>\\n          </tr>\\n          <tr>\\n            <td><strong>API backend</strong></td>\\n            <td>GKE (private cluster) running FastAPI, multiple replicas</td>\\n            <td>Strong network controls, sidecars, private egress, platform patterns</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Object storage</strong></td>\\n            <td>Cloud Storage (GCS) buckets (raw docs + processed artifacts)</td>\\n            <td>Retention policies, CMEK (KMS), uniform bucket-level access</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Canonical store</strong></td>\\n            <td>Cloud SQL for PostgreSQL (tenants, users, documents, chunks metadata)</td>\\n            <td>Private IP + IAM DB auth where possible; RLS optional backstop</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Async pipeline</strong></td>\\n            <td>Pub/Sub for events + Cloud Tasks for controlled retries to workers</td>\\n            <td>Pub/Sub for fan-out; Tasks for rate-limited HTTP execution + DLQ</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Document extraction</strong></td>\\n            <td>Option A: Document AI (OCR/forms) called by an ingestion worker</td>\\n            <td>Best for scans/PDFs; keep outputs minimal and stored internally</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Search / vectors</strong></td>\\n            <td>(Your design) Elasticsearch/OpenSearch hosted/managed or in-cluster</td>\\n            <td>Must enforce tenant/corpus filters; isolate indices or filter fields</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Secrets</strong></td>\\n            <td>Secret Manager + CMEK KMS keys</td>\\n            <td>Rotation + least privilege; avoid secrets baked into images</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Observability</strong></td>\\n            <td>Cloud Logging + Cloud Monitoring + Cloud Trace</td>\\n            <td>Structured logs + trace correlation IDs; retention controls</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Egress to external LLM</strong></td>\\n            <td>Private egress via NAT + egress proxy / allowlist + DLP/redaction hooks</td>\\n            <td>Network allowlisting + audit + bounded payload rules</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Key boundary:</strong> Human users authenticate to <em>your app</em> (OIDC token). Your workloads authenticate to GCP\\n        using <em>workload identity</em> + service accounts. End users do not get GCP IAM access to buckets/DB.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"2-document-extraction-tooling-where-implemented-and-why\\">2) Document extraction tooling: where implemented and why</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        Extraction is almost never done in the interactive API path. It is an <strong>async worker responsibility</strong>.\\n        The normal pattern:\\n      </p>\\n      <ol>\\n        <li>User uploads document \u2192 stored in <code>gs://raw-docs</code></li>\\n        <li>Upload emits an event (Pub/Sub) \u2192 ingestion worker picks it up</li>\\n        <li>Worker performs extraction (Document AI / libraries) \u2192 stores canonical text in Cloud SQL + processed text in GCS</li>\\n        <li>Worker generates chunks + embeddings \u2192 writes to vector store (with strict tenant/corpus tags)</li>\\n      </ol>\\n\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Option A (common): Document AI</div>\\n          <ul>\\n            <li>Best when you have PDFs, scans, mixed layouts, forms</li>\\n            <li>Managed OCR quality tends to beat DIY OCR</li>\\n            <li>Worker calls Document AI API; you store only needed output</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Option B: Self-managed extractors</div>\\n          <ul>\\n            <li>Apache Tika / unstructured / custom parsers in a worker container</li>\\n            <li>Good for Office docs / HTML / text-heavy content</li>\\n            <li>More operational burden (libs, CVEs, memory spikes)</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Enterprise-friendly practice:</strong> \u201cextract \u2192 store canonical text internally \u2192 index\u201d\\n        and keep extraction strictly async with retries and DLQs.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"3-why-gke-for-the-backend-and-what-cloud-run-would-change\\">3) Why GKE for the backend (and what Cloud Run would change)</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Why choose GKE (common in banks)</div>\\n          <ul>\\n            <li><strong>Private cluster</strong> + tighter network isolation patterns</li>\\n            <li>Sidecars (proxies, policy agents), service mesh (if required)</li>\\n            <li>More predictable performance under heavy concurrency</li>\\n            <li>Consistent \u201cplatform standard\u201d if the org runs many services on GKE</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">When Cloud Run is acceptable</div>\\n          <ul>\\n            <li>Faster initial delivery, simpler operations</li>\\n            <li>Great for stateless HTTP services</li>\\n            <li>Still supports service identities, private networking (with setup)</li>\\n            <li>Less flexibility for complex in-cluster patterns</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <strong>Decision framing:</strong> In a large org, you usually align with the platform team\u2019s \u201cgolden path\u201d.\\n        If the enterprise runs private GKE landing zones, GKE reduces approval friction.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"4-why-pub-sub-cloud-tasks-and-what-they-solve\\">4) Why Pub/Sub + Cloud Tasks (and what they solve)</h2>\\n    <div class=\\"card\\">\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Pub/Sub: event distribution (fan-out)</div>\\n          <ul>\\n            <li>\u201cSomething happened\u201d messaging (document uploaded, extraction complete)</li>\\n            <li>Multiple consumers can subscribe (indexer, audit, notifications)</li>\\n            <li>High throughput and decoupling</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Cloud Tasks: controlled execution (rate + retries)</div>\\n          <ul>\\n            <li>Push a specific HTTP job to a worker endpoint</li>\\n            <li>Built-in retry + scheduling + DLQ patterns</li>\\n            <li>Enforce per-queue throughput (useful for external API limits)</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Typical pattern:</strong> Pub/Sub announces the event; Cloud Tasks is used for the \u201cdo work\u201d step\\n        when you need strict retry, backoff, and rate control.\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>What about Kafka?</strong> Acceptable in some orgs, but usually heavier to operate. If your enterprise already has it,\\n        it\u2019s a viable alternative. Otherwise Pub/Sub is the GCP-native path.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"5-latency-targets-what-s-acceptable-and-how-to-meet-it\\">5) Latency targets: what\u2019s acceptable and how to meet it</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        You should define <strong>SLOs</strong> separately for interactive query and async ingestion.\\n        Concrete targets that work for exec Q&amp;A:\\n      </p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Path</th>\\n            <th>Target (p50 / p95)</th>\\n            <th>How you hit it</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>/query (interactive)</strong></td>\\n            <td>p50: 2\u20134s, p95: 6\u201310s</td>\\n            <td>Async I/O, fast retrieval (sub-second), bounded context size, caching, LLM timeouts</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Retrieval alone</strong></td>\\n            <td>p50: 100\u2013300ms, p95: &lt; 800ms</td>\\n            <td>Tenant-filtered indices, warm caches, limit top_k, avoid expensive rescoring</td>\\n          </tr>\\n          <tr>\\n            <td><strong>LLM call alone</strong></td>\\n            <td>p50: 1\u20133s, p95: 5\u20138s</td>\\n            <td>Streaming responses, concurrency limits, fallback/timeout, smaller prompts</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Ingestion (async)</strong></td>\\n            <td>Minutes are fine (SLO: &lt; 15 min typical)</td>\\n            <td>Worker autoscale, retries, DLQ, document size limits, batch processing</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Practical trick:</strong> Stream the LLM answer to the UI so the user \u201csees progress\u201d even if p95 is high.\\n        It improves perceived latency.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"6-handling-1000s-of-simultaneous-users-gke-fastapi-external-llm-constraints\\">6) Handling 1000s of simultaneous users (GKE + FastAPI + external LLM constraints)</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        At scale, your true bottleneck is often <strong>the LLM endpoint</strong>, not FastAPI itself.\\n        Your strategy is: keep the API stateless and fast, and protect downstream dependencies.\\n      </p>\\n\\n      <h3 id=\\"6-1-api-layer-fastapi-on-gke-what-actually-scales\\">6.1 API layer (FastAPI on GKE) \u2014 what actually scales</h3>\\n      <ul>\\n        <li><strong>Stateless replicas:</strong> multiple pods behind a load balancer; each request carries its identity.</li>\\n        <li><strong>Async I/O:</strong> use async clients for DB/search/LLM so threads aren\u2019t blocked waiting on network.</li>\\n        <li><strong>Connection pooling:</strong> DB and HTTP clients pooled per pod; avoid per-request reconnects.</li>\\n        <li><strong>Timeouts + circuit breakers:</strong> fail fast when LLM/retrieval is degraded.</li>\\n      </ul>\\n\\n      <h3 id=\\"6-2-downstream-protection-what-keeps-you-stable\\">6.2 Downstream protection (what keeps you stable)</h3>\\n      <div class=\\"grid2\\">\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Rate limits &amp; fairness</div>\\n          <ul>\\n            <li>Per-tenant concurrency caps (avoid one tenant consuming all capacity)</li>\\n            <li>Global cap for LLM calls (protect the quota)</li>\\n            <li>Queueing for overflow (return 429 / retry-after when needed)</li>\\n          </ul>\\n        </div>\\n        <div class=\\"box\\">\\n          <div class=\\"k\\">Degradation strategies</div>\\n          <ul>\\n            <li>If retrieval slow \u2192 lower top_k / skip re-rank</li>\\n            <li>If LLM slow \u2192 shorter prompt / cheaper model / refusal with guidance</li>\\n            <li>If dependency down \u2192 return \u201ctry again\u201d with tracking ID</li>\\n          </ul>\\n        </div>\\n      </div>\\n\\n      <div class=\\"ok\\">\\n        <strong>Key point:</strong> \u201c1000s of users\u201d is fine for stateless HTTP + retrieval.\\n        The hard part is controlling <em>LLM concurrency</em> and ensuring tenant fairness.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"7-step-4-provisioning-and-dependency-tickets-what-to-raise-exactly\\">7) Step 4: Provisioning &amp; dependency tickets (what to raise, exactly)</h2>\\n    <div class=\\"card\\">\\n      <p><span class=\\"pill\\">Goal</span> Avoid being blocked mid-sprint. Treat provisioning as part of delivery.</p>\\n\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Area</th>\\n            <th>Ticket examples (concrete)</th>\\n            <th>Why it matters</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td><strong>GKE</strong></td>\\n            <td>\\n              Create namespace <code>docqa</code>; create KSA + map to GSA (workload identity);\\n              set pod security standards; enable image scanning gate in CI/CD\\n            </td>\\n            <td>Everything else depends on the runtime identity and security posture</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Data</strong></td>\\n            <td>\\n              Cloud SQL Postgres (private IP) + IAM/roles; GCS buckets: <code>raw-docs</code>, <code>processed-text</code>;\\n              retention + UBLA + CMEK\\n            </td>\\n            <td>Data stores are often the slowest approvals in enterprises</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Async</strong></td>\\n            <td>\\n              Pub/Sub topic <code>doc-uploaded</code>; subscription for ingestion worker; DLQ topic;\\n              Cloud Tasks queues <code>extract</code>, <code>index</code> with rate limits\\n            </td>\\n            <td>Reliable ingestion requires retryable, auditable async plumbing</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Security</strong></td>\\n            <td>\\n              Secret Manager secrets (DB creds / API keys); KMS keys; log retention policy; audit log schema sign-off\\n            </td>\\n            <td>Without this, you\u2019ll fail review conditions late</td>\\n          </tr>\\n          <tr>\\n            <td><strong>Egress</strong></td>\\n            <td>\\n              External egress allowlist to LLM endpoint; egress proxy approval; NAT/IP ranges; DLP/redaction controls\\n            </td>\\n            <td>External calls are a common compliance blocker\u2014start early</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Lead technique:</strong> Every ticket should specify: <em>service name</em>, <em>data classification</em>,\\n        <em>identity (GSA)</em>, <em>network path</em>, and <em>evidence needed for approval</em>.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"8-step-5-engineering-kickoff-internal-make-good-unambiguous\\">8) Step 5: Engineering kickoff (internal) \u2014 make \u201cgood\u201d unambiguous</h2>\\n    <div class=\\"card\\">\\n      <p><span class=\\"pill\\">Goal</span> Align the team on scope, contracts, evaluation gates, and Definition of Done.</p>\\n\\n      <h3 id=\\"kickoff-checklist\\">Kickoff checklist</h3>\\n      <ul>\\n        <li><strong>Confirm vertical slice:</strong> the exact demo you will deliver at end of Sprint 1</li>\\n        <li><strong>API contracts:</strong> <code>/auth/bootstrap</code>, <code>/query</code>, <code>/ingest</code> (request/response + error codes)</li>\\n        <li><strong>Evaluation gates:</strong> golden set baseline, citation correctness checks, regression threshold</li>\\n        <li><strong>Definition of Done:</strong> includes tests + logs/metrics/traces + safety checks</li>\\n        <li><strong>Integration points:</strong> schema for docs/chunks, tenant/corpus tag format, log schema</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>Best practice:</strong> write the vertical slice as a single end-to-end \u201cdemo script\u201d\\n        (login \u2192 ingest sample \u2192 ask question \u2192 see citations \u2192 check audit log entry).\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Common rework source:</strong> engineers implement in parallel without agreed contracts.\\n        Freeze the first version of schemas and endpoints early.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"9-quick-acceptable-alternatives-cheat-sheet-if-approvals-block-you\\">9) Quick \u201cacceptable alternatives\u201d cheat sheet (if approvals block you)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Need</th>\\n            <th>Preferred</th>\\n            <th>Acceptable alternative (for pilot)</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Runtime platform</td>\\n            <td>GKE private cluster</td>\\n            <td>Cloud Run (if allowed by platform/security), then migrate later</td>\\n          </tr>\\n          <tr>\\n            <td>Async jobs</td>\\n            <td>Pub/Sub + Cloud Tasks</td>\\n            <td>Pub/Sub only (simpler), but less fine-grained rate limiting for HTTP work</td>\\n          </tr>\\n          <tr>\\n            <td>Extraction</td>\\n            <td>Document AI</td>\\n            <td>Basic parser for text/PDF-only corpus (limit scope to reduce risk)</td>\\n          </tr>\\n          <tr>\\n            <td>Search/vectors</td>\\n            <td>OpenSearch/Elastic w/ filters</td>\\n            <td>Postgres + pgvector for pilot (lower scale, simpler ops) if acceptable</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n\\n      <div class=\\"callout\\">\\n        <strong>Leadership message:</strong> \u201cWe can deliver a safe vertical slice with reduced scope while approvals for the full target stack complete.\u201d\\n      </div>\\n    </div>\\n  </div>"}'),l={title:"Steps 4\u20135 on GCP: Services, Provisioning, Latency, and Scale",slug:"/part1-enterprise-ai-delivery/11-provisioning-services-scale",description:"This tutorial expands Step 4 and Step 5 for your multi-tenant Document Q&A system on GCP. It answers: which exact services you provision, why GKE / Pub/Sub / Cloud Tasks, what latency targets are acceptable, and how t...",sidebar_label:"11. Provisioning, services, scale",pagination_label:"11. Provisioning, services, scale",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},u=[];function p(e){return(0,i.jsx)(a.A,{content:o})}function g(e={}){const{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(p,{...e})}):p()}}}]);